INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Desktop immer leistungsstärker als ein Laptop?', 2, '[{"text": "Nein", "correct": true, "because": "High-End-Laptops können mithalten"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente ist für einen Desktop-PC essenziell?', 3, '[{"text": "Mainboard", "correct": true, "because": "Verbindet alle Teile"}, {"text": "Monitor", "correct": false, "because": "Optional bei Servernutzung"}, {"text": "Tastatur", "correct": false, "because": "Nur Eingabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Desktop-System?', 5, '[{"text": "Erweiterbarkeit", "correct": true, "because": "Leichter Hardwaretausch"}, {"text": "Hohe Leistung", "correct": true, "because": "Platz für starke Komponenten"}, {"text": "Mobilität", "correct": false, "because": "Nicht mobil"}, {"text": "Geringer Stromverbrauch", "correct": false, "because": "Höher als Laptops"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Desktops sind leicht aufrüstbar. b) Sie brauchen immer einen Monitor.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Monitor optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines Systems fürs Büro?', 4, '[{"text": "Prozessorleistung", "correct": false, "because": "Wichtig für Aufgaben"}, {"text": "RAM-Größe", "correct": false, "because": "Beeinflusst Multitasking"}, {"text": "Gehäusefarbe", "correct": true, "because": "Rein ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Desktop ohne GPU läuft?', 2, '[{"text": "Ja", "correct": true, "because": "Integrierte Grafik möglich"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend separat nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Stromversorgung bei einem Desktop?', 3, '[{"text": "Versorgt alle Komponenten", "correct": true, "because": "Ohne PSU kein Betrieb"}, {"text": "Regelt die Temperatur", "correct": false, "because": "Das machen Lüfter"}, {"text": "Erhöht die Taktfrequenz", "correct": false, "because": "Nicht ihre Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten machen einen Desktop leistungsstark?', 5, '[{"text": "CPU", "correct": true, "because": "Rechenleistung"}, {"text": "RAM", "correct": true, "because": "Schneller Datenzugriff"}, {"text": "Bluetooth", "correct": false, "because": "Nur Konnektivität"}, {"text": "Lautsprecher", "correct": false, "because": "Nur Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Desktops sind für Server geeignet. b) Sie sind immer laut. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lautstärke hängt von Kühlung ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen funktionalen Desktop?', 4, '[{"text": "Prozessor", "correct": false, "because": "Kernkomponente"}, {"text": "Netzteil", "correct": false, "because": "Stromversorgung nötig"}, {"text": "Externe Maus", "correct": true, "because": "Alternative Eingaben möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Desktops nur für Gaming?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Büro und Server"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen einen Desktop flexibel?', 4, '[{"text": "Erweiterungsslots", "correct": true, "because": "Für neue Hardware"}, {"text": "Modulares Design", "correct": true, "because": "Einfacher Austausch"}, {"text": "Leichtgewicht", "correct": false, "because": "Nicht mobil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Desktop ohne Internet nutzlos ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Lokale Aufgaben möglich"}, {"text": "Ja", "correct": false, "because": "Internet nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Konfiguration eines Systems?', 3, '[{"text": "Kompatibilität der Teile", "correct": true, "because": "Sichert Funktion"}, {"text": "Geringer Preis", "correct": false, "because": "Qualität zählt"}, {"text": "Optisches Design", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Desktops haben mehr Platz für Lüfter. b) Sie sind immer günstiger als Laptops.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Preis variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Features sind für einen Arbeits-PC wichtig?', 5, '[{"text": "Hohe RAM-Kapazität", "correct": true, "because": "Für Multitasking"}, {"text": "Schnelle SSD", "correct": true, "because": "Beschleunigt Zugriff"}, {"text": "Integrierte Webcam", "correct": false, "because": "Nicht zwingend"}, {"text": "RGB-Beleuchtung", "correct": false, "because": "Nur Deko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Desktop unwichtig?', 3, '[{"text": "Kühlung", "correct": false, "because": "Schützt Hardware"}, {"text": "Stromversorgung", "correct": false, "because": "Essenziell"}, {"text": "Tragegriff", "correct": true, "because": "Nicht mobil"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Braucht ein Desktop immer eine dedizierte GPU?', 3, '[{"text": "Nein", "correct": true, "because": "Integrierte Grafik reicht oft"}, {"text": "Ja", "correct": false, "because": "Abhängig vom Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Desktop als Server taugt?', 2, '[{"text": "Ja", "correct": true, "because": "Mit richtiger Konfig möglich"}, {"text": "Nein", "correct": false, "because": "Nicht nur für Clients"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature macht einen Desktop langlebig?', 4, '[{"text": "Aufrüstbarkeit", "correct": true, "because": "Anpassung an neue Anforderungen"}, {"text": "Kleine Bauform", "correct": false, "because": "Eher bei Laptops"}, {"text": "Geringes Gewicht", "correct": false, "because": "Nicht relevant"}]');
